package ctxtest

import (
	"emon/docprobe"
	"emon/port"
	"testing"
)

func Weave(x *port.Cells, y *port.Cells) int32 {
	port.CellsPush(x, 11)
	port.CellsPush(y, 22)
	port.CellsPush(y, 33)
	return port.CellsLen(x) + port.CellsLen(y)
}

func Bump(d *docprobe.Doc) int32 {
	d.N += 1
	port.CellsPush(d.A, d.N)
	return Weave(d.A, d.B)
}

func TestAFreshContextHasEmptyFields(emonT *testing.T) {
	var d *docprobe.Doc = docprobe.NewDoc()
	port.AssertEq(emonT, port.CellsLen(d.A), 0, "a is empty")
	port.AssertEq(emonT, port.CellsLen(d.B), 0, "b is empty")
	port.AssertEq(emonT, port.BufLen(d.Png), 0, "png is empty")
	port.AssertEq(emonT, port.BufLen(d.Spare), 0, "spare is empty")
	port.AssertEq(emonT, d.N, 0, "n is zero")
	port.AssertText(emonT, d.Out, "", "out is empty")
}

func TestTwoFieldsAreLentInOneCall(emonT *testing.T) {
	var d *docprobe.Doc = docprobe.NewDoc()
	port.AssertEq(emonT, Weave(d.A, d.B), 3, "one cell in a, two in b")
	port.AssertEq(emonT, port.CellsAt(d.A, 0), 11, "a got its own push")
	port.AssertEq(emonT, port.CellsAt(d.B, 0), 22, "b got its pushes")
	port.AssertEq(emonT, port.CellsAt(d.B, 1), 33, "in order")
	port.AssertEq(emonT, port.CellsLen(d.A), 1, "a was not written twice")
}

func TestAFunctionThatTakesTheContextLendsItsFields(emonT *testing.T) {
	var d *docprobe.Doc = docprobe.NewDoc()
	port.AssertEq(emonT, Bump(d), 4, "a holds 1 and 11, b holds 22 and 33")
	port.AssertEq(emonT, d.N, 1, "n was counted")
	port.AssertEq(emonT, Bump(d), 8, "the second call sees the first")
	port.AssertEq(emonT, d.N, 2, "n again")
	port.AssertEq(emonT, port.CellsAt(d.A, 0), 1, "the first push")
	port.AssertEq(emonT, port.CellsAt(d.A, 2), 2, "the second push, after weave's")
}

func TestSwapExchangesWhatTheFieldsHold(emonT *testing.T) {
	var d *docprobe.Doc = docprobe.NewDoc()
	port.CellsPush(d.A, 1)
	port.CellsPush(d.A, 2)
	port.CellsPush(d.A, 3)
	port.CellsPush(d.B, 9)
	port.CellsSwap(d.A, d.B)
	port.AssertEq(emonT, port.CellsLen(d.A), 1, "a holds what b held")
	port.AssertEq(emonT, port.CellsAt(d.A, 0), 9, "9")
	port.AssertEq(emonT, port.CellsLen(d.B), 3, "b holds what a held")
	port.AssertEq(emonT, port.CellsAt(d.B, 2), 3, "3")
	port.CellsPush(d.A, 10)
	port.AssertEq(emonT, port.CellsLen(d.A), 2, "a still grows")
	port.AssertEq(emonT, port.CellsLen(d.B), 3, "and b is untouched by it")
}

func TestCopyIntoReplacesAndDoesNotAlias(emonT *testing.T) {
	var d *docprobe.Doc = docprobe.NewDoc()
	port.CellsPush(d.A, 5)
	port.CellsPush(d.A, 6)
	port.CellsPush(d.B, 99)
	port.CellsPush(d.B, 98)
	port.CellsPush(d.B, 97)
	port.CellsCopyInto(d.B, d.A)
	port.AssertEq(emonT, port.CellsLen(d.B), 2, "b is a, whatever it held")
	port.AssertEq(emonT, port.CellsAt(d.B, 0), 5, "5")
	port.AssertEq(emonT, port.CellsAt(d.B, 1), 6, "6")
	port.CellsPush(d.A, 7)
	port.CellsSet(d.B, 0, 50)
	port.AssertEq(emonT, port.CellsLen(d.B), 2, "a growing does not grow the copy")
	port.AssertEq(emonT, port.CellsAt(d.A, 0), 5, "and the copy writing does not reach a")
	port.BufPush(d.Png, 1)
	port.BufPush(d.Png, 255)
	port.BufPush(d.Spare, 9)
	port.BufCopyInto(d.Spare, d.Png)
	port.AssertEq(emonT, port.BufLen(d.Spare), 2, "spare is png, whatever it held")
	port.AssertEq(emonT, port.BufAt(d.Spare, 1), 255, "255 reads back unsigned")
	port.BufSet(d.Spare, 0, 77)
	port.AssertEq(emonT, port.BufAt(d.Png, 0), 1, "writing the copy does not reach png")
}

func TestACloneIsIndependent(emonT *testing.T) {
	var d *docprobe.Doc = docprobe.NewDoc()
	port.CellsPush(d.A, 4)
	port.BufPush(d.Png, 8)
	port.TextAscii(d.Out, "ab")
	d.N = 3
	var e *docprobe.Doc = d.Clone()
	port.AssertEq(emonT, port.CellsAt(e.A, 0), 4, "the clone has a's cell")
	port.AssertEq(emonT, port.BufAt(e.Png, 0), 8, "and png's byte")
	port.AssertText(emonT, e.Out, "ab", "and out's text")
	port.AssertEq(emonT, e.N, 3, "and n")
	port.CellsPush(e.A, 5)
	port.BufPush(e.Png, 6)
	port.TextAscii(e.Out, "c")
	e.N = 4
	port.CellsPush(d.A, 7)
	port.AssertEq(emonT, port.CellsLen(d.A), 2, "the original grew by its own push only")
	port.AssertEq(emonT, port.CellsAt(d.A, 1), 7, "7")
	port.AssertEq(emonT, port.BufLen(d.Png), 1, "png untouched by the clone's write")
	port.AssertText(emonT, d.Out, "ab", "out untouched")
	port.AssertEq(emonT, d.N, 3, "n untouched")
	port.AssertEq(emonT, port.CellsLen(e.A), 2, "the clone grew by its own")
	port.AssertEq(emonT, port.CellsAt(e.A, 1), 5, "5, not 7")
	port.AssertText(emonT, e.Out, "abc", "the clone's text")
	port.AssertEq(emonT, e.N, 4, "the clone's n")
}

func TestFreeEmptiesAndTheArenaIsUsableAgain(emonT *testing.T) {
	var d *docprobe.Doc = docprobe.NewDoc()
	port.CellsPush(d.A, 1)
	port.CellsPush(d.A, 2)
	port.CellsFree(d.A)
	port.AssertEq(emonT, port.CellsLen(d.A), 0, "freed")
	port.AssertEq(emonT, port.CellsPush(d.A, 42), 0, "the next push lands at 0")
	port.AssertEq(emonT, port.CellsAt(d.A, 0), 42, "42")
	port.CellsFree(d.B)
	port.AssertEq(emonT, port.CellsLen(d.B), 0, "freeing an empty one is allowed")
}
